corefile:
alpha.example:53 {
    file /etc/coredns/zones/alpha.example.zone
}

zeta.example:53 {
    file /etc/coredns/zones/zeta.example.zone
}

internal.corp:53 {
    forward . 10.1.0.53:5353 [fd00::53]:53 {
        policy sequential
    }
}

corp:53 {
    forward . 10.0.0.53:53 {
        policy sequential
    }
}

.:53 {
    errors
    health
    ready
    loop
    reload
    cache 30
    forward . 1.1.1.1:53 [2606:4700:4700::1111]:53 {
        policy sequential
    }
}
